mapper.select:
select m.MID,dic.DICVALUE as MODULARGROUP,m.MODULARNAME,m.PARENTID,m.ICON,m.MODULARNO,mr.ROLEID,mr.ISCOMMONUSE,mr.ORDERBY,m.ORDERBY as MODULARORDERBY,m.MODULARGROUPTYPE from AP_ROLEMODULAR mr inner join AP_MODULAR m on mr.MODULARID=m.MID left join CF_DICTIONARY dic on m.MODULARGROUPTYPE=dic.DICKEY and dic.DICTYPEKEY='ModularGroupName' where 1=1 and m.PARENTID is null
and mr.ROLEID=#{roleId}
order by m.ORDERBY

select *from ( select m.MID, dic.DICVALUE as MODULARGROUP, m.MODULARNAME, m.PARENTID, m.ICON, m.MODULARNO, mr.ISDISPLAY, mr.ORDERBY,m.MODULARGROUPTYPE from AP_USERUSEMODULAR mr inner join AP_MODULAR m on mr.MODULARID = m.MID inner join AP_ROLEMODULAR rm on m.MID=rm.MODULARID and mr.ROLEID=rm.ROLEID left join CF_DICTIONARY dic on m.MODULARGROUPTYPE=dic.DICKEY and dic.DICTYPEKEY='ModularGroupName' where 1=1 and m.PARENTID is null and rm.ROLEID=#{roleId}
and mr.USERID=#{userId}
order by mr.ORDERBY ) t limit 7

select *from ( select m.MID,dic.DICVALUE as MODULARGROUP,m.MODULARNAME,m.PARENTID,m.ICON,m.MODULARNO,mr.ROLEID,mr.ISCOMMONUSE,mr.ORDERBY,m.MODULARGROUPTYPE from AP_ROLEMODULAR mr inner join AP_MODULAR m on mr.MODULARID=m.MID left join CF_DICTIONARY dic on m.MODULARGROUPTYPE=dic.DICKEY and dic.DICTYPEKEY='ModularGroupName' where 1=1 and mr.ISCOMMONUSE=1
and mr.ROLEID=#{roleId}
order by m.ORDERBY ) t limit 7

select m.MID,dic.DICVALUE as MODULARGROUP,m.MODULARNAME,m.PARENTID,m.ICON,m.MODULARNO,m.ORDERBY,m.MODULARGROUPTYPE, (select m1.MODULARNAME from AP_MODULAR m1 where m1.MID = m.PARENTID) as PARENTMODULARNAME from AP_MODULAR m left join CF_DICTIONARY dic on m.MODULARGROUPTYPE=dic.DICKEY and dic.DICTYPEKEY='ModularGroupName' where 1=1
and m.MID=#{MID}
order by m.ORDERBY

select m.MID,m.MODULARNAME,m.PARENTID,m.ICON,m.MODULARNO,mr.ROLEID from AP_ROLEMODULAR mr inner join AP_MODULAR m on mr.MODULARID=m.MID where 1=1 and m.PARENTID is not null
and mr.ROLEID=#{roleId}
order by m.PARENTID
